#include "tests/support/socket/response_hex_test_fixture.hpp"
using namespace response_hex_test;
namespace {
void bytes(){
    for(unsigned byte=0;byte<256;++byte)for(bool heap:{false,true}){Fixture f;const std::string input(1,static_cast<char>(byte));f.seed(input,heap?31:15);const auto data=s::receive_buffer_address(f.f.value);f.encode();check(f.text()==oracle(input)&&f.f.value.size_10==2&&s::receive_buffer_address(f.f.value)==data,"all256 bytes lowercase hex oracle with inline/heap spare capacity");check(f.f.memory.view(data+2,1)[0]==0&&f.effects.fills.size()==1&&f.effects.fills[0].count==1,"spare fill and final NUL before backward encode");}
    std::vector<std::uint64_t> sizes;for(std::uint64_t n=0;n<70;++n)sizes.push_back(n);for(auto n:{128ULL,256ULL,2047ULL,2048ULL,2049ULL,4094ULL,4095ULL,8192ULL})sizes.push_back(n);
    for(auto size:sizes)for(unsigned mode:{0U,1U,2U}){
        Fixture f;std::string input;for(std::size_t i=0;i<size;++i)input.push_back(static_cast<char>((i*71+size)&255));const auto cap=std::max<std::uint64_t>(mode==1?31:15,mode==2?size*2+16:size);f.seed(input,cap);const auto prior=f.f.value;const auto old_data=s::receive_buffer_address(f.f.value);f.encode();
        check(f.text()==oracle(input)&&f.f.value.size_10==size*2,"binary/embedded NUL/length anchors independent full byte oracle");
        if(!size){check(f.f.value.storage_00==prior.storage_00&&f.f.value.capacity_18==prior.capacity_18&&f.effects.fills.empty()&&f.effects.calls.empty()&&f.f.api.allocations.empty(),"empty encode is exact no-op, no fill/copy/allocation");continue;}
        check(f.f.memory.view(s::receive_buffer_address(f.f.value)+size*2,1)[0]==0&&f.effects.fills.size()==1&&f.effects.fills[0].byte==0&&f.effects.fills[0].count==size,"resized terminator and original-count zero fill contract");
        if(size<=cap-size){check(f.f.value.capacity_18==cap&&s::receive_buffer_address(f.f.value)==old_data&&f.f.api.allocations.empty()&&f.effects.calls.empty(),"spare path retains capacity/pointer without copy or allocation");}
        else{const auto capacity=std::max<std::uint64_t>((size*2)|15,cap+cap/2);check(f.f.value.capacity_18==capacity&&f.f.api.allocations==std::vector<std::uint64_t>{capacity+1+(capacity+1>=4096?39U:0U)}&&f.effects.calls.size()==1&&f.effects.calls[0].count==size,"actual008350 rounded/geometric capacity, original payload copy and aligned allocation size");check(f.f.api.frees.size()==(cap>15?1U:0U),"growth frees only old heap allocation");}
    }
    {Fixture f;f.f.value.size_10=0;f.f.value.capacity_18=UINT64_MAX;f.f.value.storage_00.fill(0xcc);const auto before=f.f.value;f.f.regions.fill({});f.encode();check(f.f.value.storage_00==before.storage_00&&f.f.value.capacity_18==UINT64_MAX&&!f.f.value.size_10,"even empty unmapped prefix is untouched; no fabricated NUL or pointer validation");}
    {Fixture f;std::string input;for(unsigned b=0;b<256;++b)input.push_back(static_cast<char>(b));f.seed(input,256);f.encode();check(f.text()==oracle(input)&&f.f.value.size_10==512,"whole byte alphabet preserves input during backward overlapping expansion");}
}
void live_and_failures(){
    {Fixture f;f.seed("ABC",31);f.effects.after_fill=[&](){f.f.value.size_10=1;};f.encode();auto data=f.f.memory.view(s::receive_buffer_address(f.f.value),6);check(std::string(data.begin(),data.end())=="414243"&&f.f.value.size_10==1,"cached original loop bound despite fill callback size mutation; no later metadata overwrite");}
    {Fixture f;f.seed("ABC",31);const auto old=s::receive_buffer_address(f.f.value);auto& other=f.f.add(32);std::copy_n("XYZ",3,other.bytes.begin());f.effects.after_fill=[&](){b::word(f.f.value.storage_00,other.raw);};f.encode();auto data=f.f.memory.view(other.raw,6);check(std::string(data.begin(),data.end())=="58595a"&&f.f.memory.view(old+6,1)[0]==0&&other.bytes[6]==0xcc,"encoder reloads live pointer after fill; resize NUL still uses cached original tail");}
    for(bool after:{false,true}){Fixture f;f.seed("ABC",15);const auto before=f.f.value.storage_00;auto fail=[](){throw Failure{9};};if(after)f.effects.after_fill=fail;else f.effects.before_fill=fail;rejects<Failure>([&]{f.encode();});check(f.f.value.size_10==6&&f.f.value.storage_00[0]=='A'&&f.f.value.storage_00[1]=='B'&&f.f.value.storage_00[2]=='C'&&f.f.value.storage_00[6]==before[6],"fill failure leaves doubled size before encode/NUL, no rollback");check(f.f.value.storage_00[3]==(after?0:before[3]),"before/after fill prefixes distinguished");}
    {Fixture f;f.seed("0123456789abcdef",16);const auto before=f.f.value;f.f.api.on_allocate=[](){throw Failure{9};};rejects<Failure>([&]{f.encode();});check(f.f.value.storage_00==before.storage_00&&f.f.value.size_10==16&&f.f.value.capacity_18==16,"growth allocation failure before metadata or encode");}
    {Fixture f;f.seed("0123456789abcdef",16);const auto before=f.f.value.storage_00;f.effects.before=[](unsigned){throw Failure{9};};rejects<Failure>([&]{f.encode();});check(f.f.value.size_10==32&&f.f.value.capacity_18==47&&f.f.value.storage_00==before&&f.f.api.frees.empty(),"growth COPY failure leaves new metadata/old pointer, encoder never starts");}
    {Fixture f;f.seed("0123456789abcdef",16);const auto before=f.f.value.storage_00;f.f.api.on_free=[](){throw Failure{9};};rejects<Failure>([&]{f.encode();});check(f.f.value.size_10==32&&f.f.value.storage_00==before&&f.effects.calls.size()==1&&f.effects.fills.size()==1,"old-free exception before new pointer publication and encode loop");}
    {Fixture f;f.seed("AB",15);const auto base=s::receive_buffer_address(f.f.value);f.effects.after_fill=[&](){f.f.regions[0].bytes=f.f.value.storage_00;f.f.regions[0].bytes=f.f.regions[0].bytes.first(2);f.f.regions[1]={base+3,std::span<std::uint8_t>(f.f.value.storage_00).subspan(3,2)};};rejects<s::UnsupportedInput>([&]{f.encode();});check(f.f.value.size_10==4&&f.f.value.storage_00[3]=='2'&&f.f.value.storage_00[2]==0&&f.f.value.storage_00[0]=='A',"bounded high-store failure proves low nibble written before high nibble");}
    {Fixture f;f.seed("AB",15);f.f.value.size_10=0x8000000000000000ULL;rejects<s::UnsupportedInput>([&]{f.encode();});check(!f.f.value.size_10&&!f.f.value.storage_00[0]&&f.effects.fills.empty()&&f.f.api.allocations.empty(),"symbolic doubled-size wrap writes size0/NUL before bounded original-count read failure; no new overflow terminal");}
    {Fixture f;f.f.value.size_10=f.f.value.capacity_18=0x7fffffffffffffffULL;try{f.encode();r::unexpected();}catch(const b::Terminal& e){check(e.kind==1&&f.f.value.size_10==0x7fffffffffffffffULL&&f.f.api.allocations.empty(),"nonwrapped huge growth delegates actual008350 length terminal");}}
}
}
int main(){try{bytes();live_and_failures();std::cout<<"PASS: "<<checks<<" socket response hex checks; actual03d190 and reused resize/grow, all byte values, binary/backward overlap oracle, exact empty no-op, live prefix and failure/wrap states\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected terminal\n";return 1;}}


